# Hypothesis: a metaclass __call__ annotated to return object makes checkers infer object for Config(...), while the runtime returns the cached Config instance.
from typing import reveal_type


class Registry(type):
    cache: dict[type, object] = {}

    def __call__(cls, *args: object, **kwargs: object) -> object:
        if cls not in Registry.cache:
            Registry.cache[cls] = super().__call__(*args, **kwargs)
        return Registry.cache[cls]


class Config(metaclass=Registry):
    def __init__(self, name: str) -> None:
        self.name = name


first = Config("alpha")
second = Config("beta")
reveal_type(first)
reveal_type(second)
assert first is second
assert first is Config("gamma")
